var GRAM=[{"id": "b1", "ok": "The museum closed early; the storm had cut the power.", "bad": "The museum closed early, the storm had cut the power.", "t": {"tr": "Bağımsız iki cümle: virgül yetmez", "en": "Two complete sentences: a comma is not enough"}, "r": {"tr": "İki tam cümleyi (öznesi ve yüklemi olan) sadece virgülle bağlayamazsın. Nokta, noktalı virgül ya da 'virgül + and/but/so' kullan.", "en": "You cannot join two complete sentences (each with its own subject and verb) with only a comma. Use a period, a semicolon, or a comma plus and / but / so."}, "q": [{"s": "The museum closed ___ storm had knocked out the power.", "o": ["early; the", "early, the", "early the", "early, and, the"], "w": {"tr": "İki tam cümle var. Virgül tek başına bağlayamaz (comma splice); noktalı virgül bağlar.", "en": "Two complete sentences. A comma alone cannot join them (a comma splice); a semicolon can."}}, {"s": "Bees communicate through ___ forager's movements show others where flowers are.", "o": ["dance. A", "dance, a", "dance a", "dance; and a"], "w": {"tr": "İki bağımsız cümle: nokta ile ayır. 'dance; and' yanlış — noktalı virgülden sonra and gelmez.", "en": "Two independent sentences: separate them with a period. 'dance; and' is wrong: 'and' does not follow a semicolon."}}, {"s": "Gold does not ___ is used in electronics that must last for decades.", "o": ["rust, so it", "rust, it", "rust it", "rust; so, it"], "w": {"tr": "'virgül + so' iki cümleyi bağlar. Sadece virgül yetmez.", "en": "'Comma + so' joins two sentences. A comma alone is not enough."}}]}, {"id": "b2", "ok": "The trail is short, but it climbs steeply.", "bad": "The trail is short but, it climbs steeply.", "t": {"tr": "Virgül + FANBOYS (and, but, so, yet, or)", "en": "Comma + FANBOYS (and, but, so, yet, or)"}, "r": {"tr": "İki tam cümleyi 'and, but, so, yet, or, nor, for' ile bağlarken bağlacın ÖNÜNE virgül gelir, arkasına gelmez.", "en": "When you join two complete sentences with and, but, so, yet, or, nor, or for, the comma goes BEFORE the conjunction, not after it."}, "q": [{"s": "Marie Curie won a Nobel Prize in ___ later won a second one in chemistry.", "o": ["physics, and she", "physics and, she", "physics, and, she", "physics; and she"], "w": {"tr": "Virgül bağlacın önünde, arkasında değil.", "en": "The comma goes before the conjunction, not after it."}}, {"s": "The trail is ___ climbs steeply.", "o": ["short, but it", "short but, it", "short, but, it", "short; but it"], "w": {"tr": "Virgül 'but'un önüne gelir.", "en": "The comma goes before 'but'."}}, {"s": "Rain was ___ festival went ahead as planned.", "o": ["forecast, yet the", "forecast yet, the", "forecast, yet, the", "forecast: yet the"], "w": {"tr": "'yet' bir FANBOYS bağlacı: önüne virgül.", "en": "'yet' is a FANBOYS conjunction: the comma goes before it."}}]}, {"id": "b3", "ok": "The recipe needs three ingredients: flour, water, and salt.", "bad": "The recipe needs: flour, water, and salt.", "t": {"tr": "İki nokta (:) sadece TAM cümleden sonra", "en": "A colon comes only after a complete sentence"}, "r": {"tr": "İki nokta, kendinden önceki kısım tek başına tam bir cümleyse kullanılır; arkasından liste, açıklama ya da örnek gelir. 'includes:' gibi yarım cümleden sonra gelmez.", "en": "Use a colon only when the part before it could stand alone as a complete sentence. A list, an explanation, or an example follows. Never put a colon after an unfinished phrase like 'includes:'."}, "q": [{"s": "The recipe needs only three ___ flour, water, and salt.", "o": ["ingredients:", "ingredients;", "ingredients", "ingredients, which:"], "w": {"tr": "Önceki kısım tam cümle, arkası liste → iki nokta.", "en": "The first part is a complete sentence and a list follows, so use a colon."}}, {"s": "The results were ___ new drug worked.", "o": ["clear: the", "clear, the", "clear the", "clear, and, the"], "w": {"tr": "İki nokta, önceki cümleyi açıklayan cümleyi tanıtır.", "en": "A colon introduces a sentence that explains the one before it."}}, {"s": "The research team included ___ chemist, a biologist, and a physicist.", "o": ["a", ": a", "; a", "— a"], "w": {"tr": "'included' yarım kalıyor (nesnesi yok) → iki nokta konmaz.", "en": "'included' is unfinished (it needs its object), so no colon."}}]}, {"id": "b4", "ok": "Some birds migrate; others stay all year.", "bad": "Because the soil was dry; the farmers waited.", "t": {"tr": "Noktalı virgül = nokta", "en": "A semicolon works like a period"}, "r": {"tr": "Noktalı virgülün iki tarafı da tam cümle olmalı. Yan cümleden (Because…, Although…) sonra noktalı virgül gelmez. İstisna: içinde virgül olan listelerde öğeleri ayırır.", "en": "Both sides of a semicolon must be complete sentences. A dependent clause (Because…, Although…) cannot be followed by a semicolon. Exception: in a list whose items already contain commas, semicolons separate the items."}, "q": [{"s": "Some birds migrate thousands of ___ stay in the same area all year.", "o": ["miles; others", "miles, others", "miles others", "miles: and others"], "w": {"tr": "İki tam cümle: noktalı virgül.", "en": "Two complete sentences: use a semicolon."}}, {"s": "Because the soil was ___ farmers delayed planting.", "o": ["dry, the", "dry; the", "dry. The", "dry: the"], "w": {"tr": "'Because…' yan cümle; tek başına cümle değil → virgül.", "en": "'Because…' is a dependent clause and cannot stand alone, so use a comma."}}, {"s": "The tour stops in Paris, ___ Rome, Italy; and Madrid, Spain.", "o": ["France;", "France,", "France:", "France"], "w": {"tr": "Öğelerin içinde virgül var → öğeleri noktalı virgülle ayır.", "en": "The items already contain commas, so separate them with semicolons."}}]}, {"id": "b5", "ok": "Kepler—who studied planets—was also an astrologer.", "bad": "Kepler—who studied planets, was also an astrologer.", "t": {"tr": "Ek bilgi çiftle açılır, çiftle kapanır", "en": "Extra information opens and closes with the same mark"}, "r": {"tr": "Cümleden çıkarılabilen ek bilgi iki virgül, iki tire ya da parantez arasına alınır. Hangisiyle açıldıysa onunla kapanmalı.", "en": "Information you could remove from the sentence goes between two commas, two dashes, or parentheses. Close it with the same mark you opened it with."}, "q": [{"s": "The coelacanth, a fish once thought to be ___ found alive in 1938.", "o": ["extinct, was", "extinct— was", "extinct was", "extinct; was"], "w": {"tr": "Virgülle açıldı → virgülle kapanır.", "en": "It opened with a comma, so it closes with a comma."}}, {"s": "Kepler—who studied planetary ___ also an astrologer.", "o": ["motion—was", "motion, was", "motion was", "motion; was"], "w": {"tr": "Tireyle açıldı → tireyle kapanır.", "en": "It opened with a dash, so it closes with a dash."}}, {"s": "The festival's main event (a parade through the old ___ at noon.", "o": ["town) starts", "town, starts", "town— starts", "town starts"], "w": {"tr": "Parantez açıldı → parantez kapanır.", "en": "It opened with a parenthesis, so it closes with one."}}]}, {"id": "b6", "ok": "The comedian Jemaine Clement voiced the crab.", "bad": "The comedian, Jemaine Clement, voiced the crab.", "t": {"tr": "Gerekli bilgi virgülsüz", "en": "Essential information takes no commas"}, "r": {"tr": "Kimden bahsedildiğini belirleyen bilgi virgül almaz: 'comedian Jemaine Clement', 'students who finish early', 'the painting that hangs…'.", "en": "Information that tells you WHICH person or thing you mean takes no commas: 'the comedian Jemaine Clement', 'students who finish early', 'the painting that hangs…'."}, "q": [{"s": "The Nigerian writer ___ the Nobel Prize in 1986.", "o": ["Wole Soyinka won", "Wole Soyinka, won", ", Wole Soyinka won", ", Wole Soyinka, won"], "w": {"tr": "İsim, 'writer'ın kim olduğunu belirliyor → virgül yok.", "en": "The name tells you which writer, so no commas."}}, {"s": "Students ___ the project early may present first.", "o": ["who finish", ", who finish", "who finish,", ", who finish,"], "w": {"tr": "Hangi öğrenciler? Bilgi gerekli → virgül yok.", "en": "Which students? The information is essential, so no commas."}}, {"s": "The painting ___ in the hallway was a gift.", "o": ["that hangs", ", that hangs", "that hangs,", ", that hangs,"], "w": {"tr": "'that' ile başlayan kısım her zaman gerekli bilgi → virgülsüz.", "en": "A clause starting with 'that' is always essential, so no commas."}}]}, {"id": "b7", "ok": "The scientists who studied the samples concluded that…", "bad": "The scientists who studied the samples, concluded that…", "t": {"tr": "Özne ile yüklem arasına noktalama girmez", "en": "No punctuation between subject and verb"}, "r": {"tr": "Özne ile yüklemin, yüklem ile nesnesinin arasına virgül, noktalı virgül, iki nokta ya da tire konmaz (çift virgüllü ek bilgi hariç).", "en": "Do not put a comma, semicolon, colon, or dash between a subject and its verb, or between a verb and its object (except a pair of commas around extra information)."}, "q": [{"s": "The scientists who studied the samples ___ that the rocks were volcanic.", "o": ["concluded", ", concluded", "; concluded", "— concluded"], "w": {"tr": "Özne uzun olsa da yüklemden ayrılmaz.", "en": "Even a long subject is not separated from its verb."}}, {"s": "The main goal of the program ___ to reduce waste.", "o": ["is", ", is", "—is", ": is"], "w": {"tr": "Özne + yüklem arası boş.", "en": "Nothing goes between the subject and the verb."}}, {"s": "The survey found ___ residents supported the plan.", "o": ["that most", "that, most", "that: most", ", that most"], "w": {"tr": "'found that…' nesne; araya noktalama girmez.", "en": "'found that…' is the object; no punctuation goes in between."}}]}, {"id": "b8", "ok": "They investigated how their use could be regulated.", "bad": "They investigated how could their use be regulated?", "t": {"tr": "Dolaylı soru = düz cümle", "en": "An indirect question is a statement"}, "r": {"tr": "'…asked how / wondered why / investigated whether…' ile başlayan soru, soru değildir: normal sırayla yazılır ve nokta ile biter.", "en": "A question reported after '…asked how / wondered why / investigated whether…' is not a real question: use normal word order and end with a period."}, "q": [{"s": "Researchers wanted to know why ___", "o": ["the lake was shrinking.", "was the lake shrinking?", "the lake was shrinking?", "was the lake shrinking."], "w": {"tr": "Dolaylı soru: özne + yüklem sırası, sonda nokta.", "en": "Indirect question: subject before verb, period at the end."}}, {"s": "The historian asked how ___", "o": ["the letters had survived.", "had the letters survived?", "the letters had survived?", "had the letters survived."], "w": {"tr": "Düz sıra + nokta.", "en": "Normal word order and a period."}}, {"s": "Engineers are studying whether ___", "o": ["the design can withstand earthquakes.", "can the design withstand earthquakes?", "the design can withstand earthquakes?", "can the design withstand earthquakes."], "w": {"tr": "'whether' ile gelen dolaylı soru: düz cümle.", "en": "An indirect question with 'whether' is a statement."}}]}, {"id": "b9", "ok": "After the storm passed, the crew repaired the roof.", "bad": "After the storm passed the crew repaired the roof.", "t": {"tr": "Girişteki yan cümleden sonra virgül", "en": "Comma after an opening clause"}, "r": {"tr": "Cümle 'After…, Although…, To…, Because…' gibi bir girişle başlıyorsa, giriş bitince virgül konur.", "en": "If the sentence opens with a phrase like 'After…, Although…, To…, Because…', put a comma where the opening ends."}, "q": [{"s": "After the storm ___ crew repaired the roof.", "o": ["passed, the", "passed the", "passed; the", "passed: the"], "w": {"tr": "Giriş bitti → virgül.", "en": "The opening phrase ends here, so add a comma."}}, {"s": "Although the plan was ___ council approved it.", "o": ["expensive, the", "expensive the", "expensive; the", "expensive. The"], "w": {"tr": "'Although…' yan cümle → virgül; nokta/noktalı virgül onu yalnız bırakır.", "en": "'Although…' is a dependent clause, so use a comma. A period or semicolon would leave it alone."}}, {"s": "To finish the bridge on ___ company hired extra workers.", "o": ["time, the", "time the", "time; the", "time: the"], "w": {"tr": "Giriş (To…) → virgül.", "en": "An opening 'To…' phrase is followed by a comma."}}]}, {"id": "b10", "ok": "The kit includes a map, a compass, and a whistle.", "bad": "The kit includes, a map, a compass, and a whistle.", "t": {"tr": "Listelerde virgül", "en": "Commas in a list"}, "r": {"tr": "Üç ve daha fazla öğe virgülle ayrılır; listenin ilk öğesinden önce virgül konmaz.", "en": "Separate three or more items with commas. Do not put a comma before the first item."}, "q": [{"s": "The kit includes a ___ compass, and a whistle.", "o": ["map, a", "map a", "map; a", "map: a"], "w": {"tr": "Liste öğeleri virgülle ayrılır.", "en": "List items are separated by commas."}}, {"s": "The garden grows ___", "o": ["corn, beans, and squash.", ", corn, beans, and squash.", "corn beans, and squash.", "corn, beans and, squash."], "w": {"tr": "İlk öğeden önce virgül yok; 'and'den sonra virgül yok.", "en": "No comma before the first item, and no comma right after 'and'."}}, {"s": "Volunteers planted ___ the river, and painted benches.", "o": ["trees, cleaned", "trees cleaned", "trees; cleaned", "trees: cleaned"], "w": {"tr": "Üç eylemli liste → virgül.", "en": "A list of three actions takes commas."}}]}, {"id": "f1", "ok": "The collection of ancient coins is displayed.", "bad": "The collection of ancient coins are displayed.", "t": {"tr": "Özne-yüklem uyumu: gerçek özneyi bul", "en": "Subject-verb agreement: find the real subject"}, "r": {"tr": "Yüklem, araya giren 'of the…' kısmına değil gerçek özneye uyar. 'The collection of coins IS', 'The results of the test SUPPORT'. 'Each' tekildir.", "en": "The verb agrees with the real subject, not with the 'of the…' phrase in between. 'The collection of coins IS', 'The results of the test SUPPORT'. 'Each' is singular."}, "q": [{"s": "The collection of ancient coins ___ displayed in the main hall.", "o": ["is", "are", "were", "have been"], "w": {"tr": "Özne 'collection' (tekil), 'coins' değil.", "en": "The subject is 'collection' (singular), not 'coins'."}}, {"s": "The results of the experiment ___ the hypothesis.", "o": ["support", "supports", "has supported", "is supporting"], "w": {"tr": "Özne 'results' (çoğul).", "en": "The subject is 'results' (plural)."}}, {"s": "Each of the paintings ___ a hidden signature.", "o": ["contains", "contain", "are containing", "have contained"], "w": {"tr": "'Each' her zaman tekil.", "en": "'Each' is always singular."}}]}, {"id": "f2", "ok": "Using public domain songs ensures that…", "bad": "Using public domain songs ensure that…", "t": {"tr": "-ing / to… ile başlayan özne tekildir", "en": "A subject that starts with -ing or to is singular"}, "r": {"tr": "'Reading letters', 'Using these songs', 'To build tunnels' gibi eylem öznesi tek bir şeydir → tekil yüklem (helps, ensures, was).", "en": "A subject like 'Reading letters', 'Using these songs', or 'To build tunnels' is one action, so it takes a singular verb (helps, ensures, was)."}, "q": [{"s": "Reading old letters ___ historians understand daily life.", "o": ["helps", "help", "have helped", "are helping"], "w": {"tr": "Özne 'Reading' (tek eylem) → tekil.", "en": "The subject 'Reading' is one action, so it is singular."}}, {"s": "Planting native flowers ___ bees and butterflies.", "o": ["attracts", "attract", "are attracting", "have attracted"], "w": {"tr": "-ing özne tekil.", "en": "An -ing subject is singular."}}, {"s": "Keeping the records accurate ___ difficult for the clerks.", "o": ["was", "were", "are", "have been"], "w": {"tr": "-ing özne tekil → was.", "en": "An -ing subject is singular, so 'was'."}}]}, {"id": "f3", "ok": "He considered them (the forks) dangerous.", "bad": "He considered it (the forks) dangerous.", "t": {"tr": "Zamir, yerini tuttuğu isme uyar", "en": "A pronoun matches the noun it replaces"}, "r": {"tr": "Tekil isim (company, team, committee) → it / its. Çoğul isim (forks, scientists) → they / them / their.", "en": "A singular noun (company, team, committee) takes it / its. A plural noun (forks, scientists) takes they / them / their."}, "q": [{"s": "The company announced that ___ would open a new factory.", "o": ["it", "they", "we", "one"], "w": {"tr": "'company' tekil → it.", "en": "'company' is singular, so 'it'."}}, {"s": "Forks were rare in medieval Europe, and many people considered ___ unnecessary.", "o": ["them", "it", "this", "that"], "w": {"tr": "'Forks' çoğul → them.", "en": "'Forks' is plural, so 'them'."}}, {"s": "The committee released ___ final report on Friday.", "o": ["its", "their", "it's", "they're"], "w": {"tr": "'committee' tekil → its.", "en": "'committee' is singular, so 'its'."}}]}, {"id": "f4", "ok": "The octopus can change its color.", "bad": "The octopus can change it's color.", "t": {"tr": "its / it's — their / there / they're", "en": "its / it's — their / there / they're"}, "r": {"tr": "its = onun (iyelik), it's = it is. their = onların, there = orada, they're = they are. 'its'' diye bir şey yok.", "en": "its = belonging to it; it's = it is. their = belonging to them; there = in that place; they're = they are. There is no such word as its'."}, "q": [{"s": "The octopus can change ___ color in less than a second.", "o": ["its", "it's", "its'", "their"], "w": {"tr": "İyelik → its (kesme işaretsiz).", "en": "Possession, so 'its' with no apostrophe."}}, {"s": "The students left ___ notebooks in the lab.", "o": ["their", "there", "they're", "theirs"], "w": {"tr": "Onların → their.", "en": "Belonging to them, so 'their'."}}, {"s": "___ likely that the ruins are older than first thought.", "o": ["It's", "Its", "Its'", "It is'"], "w": {"tr": "It is likely → It's.", "en": "It is likely, so 'It's'."}}]}, {"id": "f5", "ok": "Place your hands between the two antennas.", "bad": "Place your hand's between the two antenna's.", "t": {"tr": "İyelik mi, çoğul mu?", "en": "Possessive or plural?"}, "r": {"tr": "Tekil iyelik: -'s (the phrase's). Çoğul: -s (hands). Çoğul iyelik: -s' (eagles' nests). Cümlede bir şeye sahip olma yoksa kesme işareti koyma.", "en": "Singular possessive: -'s (the phrase's). Plural: -s (hands). Plural possessive: -s' (eagles' nests). No ownership, no apostrophe."}, "q": [{"s": "The ___ new owner restored it completely.", "o": ["house's", "houses", "houses'", "house"], "w": {"tr": "Tek ev, sahiplik → house's.", "en": "One house, possession, so 'house's'."}}, {"s": "Both ___ nests were built on the cliff.", "o": ["eagles'", "eagle's", "eagles", "eagles's"], "w": {"tr": "Çok kartal + sahiplik → eagles'.", "en": "Many eagles plus possession, so 'eagles''."}}, {"s": "Place your ___ on the table.", "o": ["hands", "hand's", "hands'", "hand's'"], "w": {"tr": "Sahiplik yok, sadece çoğul → hands.", "en": "No possession, just plural, so 'hands'."}}]}, {"id": "f6", "ok": "In 2023, the team published a study.", "bad": "In 2023, the team publishing a study.", "t": {"tr": "Cümlenin çekimli bir yüklemi olmalı", "en": "A sentence needs a finite verb"}, "r": {"tr": "Her cümlenin çekimli bir yüklemi olmalı (published, illuminates). '-ing', 'to…', 'having…' tek başına yüklem olamaz.", "en": "Every sentence needs a real, conjugated verb (published, illuminates). An -ing word, a to-verb, or 'having…' cannot be the main verb on its own."}, "q": [{"s": "In 2023, the team ___ a study on whale genes.", "o": ["published", "publishing", "having published", "to publish"], "w": {"tr": "Cümlenin yüklemi lazım → published.", "en": "The sentence needs a main verb, so 'published'."}}, {"s": "The lamp inside the sculpture ___ the glass.", "o": ["illuminates", "illuminating", "to illuminate", "having illuminated"], "w": {"tr": "Çekimli yüklem → illuminates.", "en": "A finite verb: 'illuminates'."}}, {"s": "The volcano, which had been quiet for centuries, ___ in 1980.", "o": ["erupted", "erupting", "to erupt", "having erupted"], "w": {"tr": "'which…' ek bilgi; ana yüklem eksik → erupted.", "en": "The 'which…' part is extra; the main verb is missing, so 'erupted'."}}]}, {"id": "f7", "ok": "A decade later, Land used the filter.", "bad": "A decade later, Land uses the filter.", "t": {"tr": "Zaman uyumu", "en": "Tense consistency"}, "r": {"tr": "Fiil zamanı metindeki zaman ifadesine uyar: 'in 1939' → geçmiş; 'each night' → geniş zaman; 'by the time … arrived' → had + V3.", "en": "Match the verb tense to the time words in the text: 'in 1939' means past; 'each night' means present; 'by the time … arrived' means had + past participle."}, "q": [{"s": "In 1929 Land invented a filter. A decade later, he ___ it to build a camera.", "o": ["used", "uses", "will use", "is using"], "w": {"tr": "Geçmişte bir olay → used.", "en": "An event in the past, so 'used'."}}, {"s": "Each night, a lamp inside the tree ___ the green bottles.", "o": ["lights", "lit", "will have lit", "had lit"], "w": {"tr": "Her gece tekrar eden durum → geniş zaman.", "en": "Something that happens every night, so simple present."}}, {"s": "By the time the rescue team arrived, the hikers ___ the summit.", "o": ["had reached", "reach", "will reach", "are reaching"], "w": {"tr": "Geçmişteki bir andan önce → had reached.", "en": "Before a moment in the past, so 'had reached'."}}]}, {"id": "f8", "ok": "Using a telescope, the astronomer spotted a comet.", "bad": "Using a telescope, a comet was spotted.", "t": {"tr": "Sarkan niteleyici (dangling modifier)", "en": "Dangling modifier"}, "r": {"tr": "Cümle 'Born in…, Using…, Exhausted…' gibi bir ifadeyle başlıyorsa, virgülden hemen sonra o işi yapan kişi/şey gelmelidir.", "en": "If a sentence opens with a phrase like 'Born in…, Using…, Exhausted…', the person or thing doing that action must come right after the comma."}, "q": [{"s": "Born in a small village, ___", "o": ["the poet wrote about rural life.", "rural life was the poet's subject.", "the poems described rural life.", "rural life filled the poet's work."], "w": {"tr": "Köyde doğan kişi şair → virgülden sonra 'the poet'.", "en": "The poet was born in the village, so 'the poet' comes right after the comma."}}, {"s": "Using a telescope, ___", "o": ["the astronomer spotted a new comet.", "a new comet was spotted.", "the comet appeared to the astronomer.", "a discovery was made by the astronomer."], "w": {"tr": "Teleskobu kullanan → astronomer.", "en": "The one using the telescope is the astronomer."}}, {"s": "Exhausted after the race, ___", "o": ["the runner sat down.", "the bench was where the runner sat.", "sitting down was what the runner did.", "the runner's shoes were left by the door."], "w": {"tr": "Yorgun olan → the runner.", "en": "The one who is exhausted is the runner."}}]}];
var GANIM={"b1": {"bad": [["The museum closed early", "A"], [",", "X"], [" the storm had cut the power.", "B"]], "ok": [["The museum closed early", "A"], [";", "F"], [" the storm had cut the power.", "B"]], "lab": {"tr": {"A": "tam cümle 1", "B": "tam cümle 2"}, "en": {"A": "sentence 1", "B": "sentence 2"}}, "n": {"tr": ["Bu cümlede iki parça var. İkisinin de öznesi ve yüklemi var. Yani ikisi de tek başına tam bir cümle.", "Aralarında sadece virgül var. Virgül iki tam cümleyi bağlayamaz. Buna {comma splice} denir ve SAT bunu çok sorar.", "Çözüm: noktalı virgül, nokta, ya da virgül artı {and, but, so} gibi bir bağlaç.", "Kısaca: iki tam cümle, tek bir virgülle birleşmez."], "en": ["This sentence has two parts. Each part has its own subject and verb, so each one is a complete sentence.", "Only a comma sits between them. A comma cannot join two complete sentences. This is called a comma splice, and the SAT tests it a lot.", "The fix: a semicolon, a period, or a comma plus a word like and, but, or so.", "In short: two complete sentences never join with just a comma."]}}, "b2": {"bad": [["The trail is short", "A"], [" but,", "X"], [" it climbs steeply.", "B"]], "ok": [["The trail is short", "A"], [", but", "F"], [" it climbs steeply.", "B"]], "lab": {"tr": {"A": "tam cümle 1", "B": "tam cümle 2"}, "en": {"A": "sentence 1", "B": "sentence 2"}}, "n": {"tr": ["İki tam cümle, {but} bağlacıyla birleşiyor.", "Virgül yanlış yerde. Bağlacın arkasına konmuş.", "Doğrusu: virgül bağlacın önüne gelir. Önce virgül, sonra {but}.", "Kısaca: iki tam cümleyi {and, but, so, yet, or} ile bağlarken virgül bağlaçtan önce gelir."], "en": ["Two complete sentences are joined by the word but.", "The comma is in the wrong place. It comes after the conjunction.", "Correct: the comma comes before the conjunction. Comma first, then but.", "In short: when and, but, so, yet, or joins two sentences, the comma goes before the conjunction."]}}, "b3": {"bad": [["The recipe needs", "A"], [":", "X"], [" flour, water, and salt.", "C"]], "ok": [["The recipe needs three ingredients", "A"], [":", "F"], [" flour, water, and salt.", "C"]], "lab": {"tr": {"A": "iki noktadan önceki kısım", "C": "liste"}, "en": {"A": "before the colon", "C": "list"}}, "n": {"tr": ["İki noktadan önceki kısma bak: {The recipe needs.} Neye ihtiyaç var? Cümle yarım kalmış.", "Yarım cümleden sonra iki nokta konmaz.", "Önce cümleyi tamamla: {The recipe needs three ingredients.} Artık tam cümle, iki nokta koyabiliriz.", "Kısaca: iki noktadan önce, tek başına tam bir cümle olmalı."], "en": ["Look at the part before the colon: The recipe needs. Needs what? The sentence is unfinished.", "A colon cannot follow an unfinished sentence.", "Finish the sentence first: The recipe needs three ingredients. Now it is complete, so the colon works.", "In short: before a colon, you need a sentence that could stand on its own."]}}, "b4": {"bad": [["Because the soil was dry", "A"], [";", "X"], [" the farmers waited.", "B"]], "ok": [["Because the soil was dry", "A"], [",", "F"], [" the farmers waited.", "B"]], "lab": {"tr": {"A": "yan cümle (Because…)", "B": "tam cümle"}, "en": {"A": "dependent clause (Because…)", "B": "complete sentence"}}, "n": {"tr": ["İlk kısım {Because} ile başlıyor. Bu bir yan cümle. Tek başına cümle olamaz.", "Noktalı virgül nokta gibidir. İki yanında da tam cümle ister. Burada sol taraf tam değil.", "Yan cümleden sonra virgül kullanılır.", "Kısaca: noktalı virgülün iki tarafı da tam cümle olmalı."], "en": ["The first part starts with Because. That makes it a dependent clause. It cannot stand alone.", "A semicolon works like a period. It needs a complete sentence on both sides. Here the left side is not complete.", "After a dependent clause, use a comma.", "In short: both sides of a semicolon must be complete sentences."]}}, "b5": {"bad": [["Kepler", "A"], ["—who studied planets", "C"], [",", "X"], [" was also an astrologer.", "B"]], "ok": [["Kepler", "A"], ["—who studied planets", "C"], ["—", "F"], [" was also an astrologer.", "B"]], "lab": {"tr": {"A": "özne", "C": "ek bilgi", "B": "yüklem"}, "en": {"A": "subject", "C": "extra information", "B": "verb"}}, "n": {"tr": ["Ortadaki {who studied planets} kısmı ek bilgi. Cümleden çıkarsan cümle yine tam kalır.", "Ek bilgi tireyle açılmış ama virgülle kapanmış. Çift uyuşmuyor.", "Tireyle açtıysan tireyle kapatırsın. Virgülle açtıysan virgülle.", "Kısaca: ek bilgi bir çift işaretle açılır ve aynı işaretle kapanır."], "en": ["The middle part, who studied planets, is extra information. Remove it and the sentence is still complete.", "The extra information opens with a dash but closes with a comma. The pair does not match.", "If you open with a dash, close with a dash. If you open with a comma, close with a comma.", "In short: extra information opens with a pair of marks and closes with the same mark."]}}, "b6": {"bad": [["The comedian", "A"], [",", "X"], [" Jemaine Clement", "C"], [",", "X"], [" voiced the crab.", "B"]], "ok": [["The comedian", "A"], [" Jemaine Clement", "C"], [" voiced the crab.", "B"]], "lab": {"tr": {"A": "özne", "C": "hangi komedyen?", "B": "yüklem"}, "en": {"A": "subject", "C": "which comedian?", "B": "verb"}}, "n": {"tr": ["Sadece {the comedian} dersek hangi komedyen olduğunu bilemeyiz. İsim, kim olduğunu belirliyor.", "Belirleyici bilgi gerekli bilgidir. Virgüllerle ayrılmaz.", "Virgülleri kaldırıyoruz. İsim özneye yapışıyor.", "Kısaca: kimden bahsedildiğini belirleyen bilgi virgülsüz yazılır. {That} ile başlayan kısım da her zaman virgülsüz."], "en": ["If we only say the comedian, we do not know which comedian. The name identifies the person.", "Identifying information is essential. It is not set off with commas.", "Remove the commas. The name attaches to the subject.", "In short: information that identifies who or what you mean has no commas. A clause starting with that never has commas."]}}, "b7": {"bad": [["The scientists who studied the samples", "A"], [",", "X"], [" concluded that the rocks were volcanic.", "B"]], "ok": [["The scientists who studied the samples", "A"], [" concluded that the rocks were volcanic.", "B"]], "lab": {"tr": {"A": "özne (uzun)", "B": "yüklem"}, "en": {"A": "subject (long)", "B": "verb"}}, "n": {"tr": ["Özne uzun: {the scientists who studied the samples.} Uzun olunca araya virgül koymak cazip geliyor.", "Ama özne ile yüklemin arasına hiçbir noktalama girmez.", "Virgülü siliyoruz. Özne doğrudan yükleme bağlanır.", "Kısaca: özne ile yüklem, yüklem ile nesne arasında noktalama yok."], "en": ["The subject is long: the scientists who studied the samples. A long subject makes a comma tempting.", "But no punctuation goes between a subject and its verb.", "Delete the comma. The subject connects directly to the verb.", "In short: no punctuation between subject and verb, or between verb and object."]}}, "b8": {"bad": [["They asked", "A"], [" how could the lake", "X"], [" be saved", "B"], ["?", "X"]], "ok": [["They asked", "A"], [" how the lake could", "F"], [" be saved", "B"], [".", "F"]], "lab": {"tr": {"A": "ana cümle", "B": "sorunun devamı"}, "en": {"A": "main clause", "B": "rest of the question"}}, "n": {"tr": ["{They asked how.} Bu doğrudan bir soru değil, bir sorunun aktarılması. Buna dolaylı soru denir.", "Dolaylı soruda soru sırası kullanılmaz ve soru işareti konmaz.", "Normal cümle sırası: {the lake could.} Sonuna da nokta.", "Kısaca: {asked how, wondered why, whether} ile gelen kısım düz cümle sırasıyla yazılır ve nokta ile biter."], "en": ["They asked how. This is not a direct question. It reports a question. We call it an indirect question.", "An indirect question does not use question word order, and it does not end with a question mark.", "Use normal order: the lake could. And end with a period.", "In short: after asked how, wondered why, or whether, use statement word order and a period."]}}, "b9": {"bad": [["After the storm passed", "A"], ["", "X"], [" the crew repaired the roof.", "B"]], "ok": [["After the storm passed", "A"], [",", "F"], [" the crew repaired the roof.", "B"]], "lab": {"tr": {"A": "giriş", "B": "asıl cümle"}, "en": {"A": "opening", "B": "main sentence"}}, "n": {"tr": ["Cümle {after the storm passed} diye bir girişle başlıyor. Asıl cümle: {the crew repaired the roof.}", "Girişin bittiği yerde bir işaret eksik.", "Girişten sonra virgül koyuyoruz.", "Kısaca: {after, although, because} ya da {to} ile başlayan girişten sonra virgül gelir."], "en": ["The sentence opens with after the storm passed. The main sentence is the crew repaired the roof.", "A mark is missing where the opening ends.", "Add a comma after the opening.", "In short: after an opening that starts with after, although, because, or to, add a comma."]}}, "b10": {"bad": [["The kit includes", "A"], [",", "X"], [" a map, a compass, and a whistle.", "C"]], "ok": [["The kit includes", "A"], [" a map, a compass, and a whistle.", "C"]], "lab": {"tr": {"A": "yüklem", "C": "liste"}, "en": {"A": "verb", "C": "list"}}, "n": {"tr": ["Burada üç öğeli bir liste var: {a map, a compass, a whistle.}", "Listenin ilk öğesinden önce virgül konmuş. Bu yanlış.", "Öğelerin arasına virgül koy, ama ilk öğeden önce koyma.", "Kısaca: liste öğelerini virgülle ayır. Listeye girerken virgül yok."], "en": ["Here is a list of three items: a map, a compass, a whistle.", "There is a comma before the first item of the list. That is wrong.", "Put commas between the items, but not before the first one.", "In short: separate list items with commas. No comma when the list begins."]}}, "f1": {"bad": [["The collection", "A"], [" of ancient coins", "C"], [" are", "X"], [" displayed.", "B"]], "ok": [["The collection", "A"], [" of ancient coins", "C"], [" is", "F"], [" displayed.", "B"]], "lab": {"tr": {"A": "gerçek özne (tekil)", "C": "araya giren kısım", "B": ""}, "en": {"A": "real subject (singular)", "C": "phrase in between", "B": ""}}, "n": {"tr": ["Ne sergileniyor? Koleksiyon. Gerçek özne {collection}, yani tekil.", "Araya giren {of ancient coins} çoğul olduğu için {are} yazılmış. Tuzak bu.", "Araya gireni yok say, özneye bak: {the collection is.}", "Kısaca: {of} ile başlayan kısmı yok say, yüklemi gerçek özneye uydur."], "en": ["What is on display? The collection. The real subject is collection, so it is singular.", "The phrase in between, of ancient coins, is plural, so someone wrote are. That is the trap.", "Ignore the phrase in between and look at the subject: the collection is.", "In short: ignore the phrase starting with of, and match the verb to the real subject."]}}, "f2": {"bad": [["Using public domain songs", "A"], [" ensure", "X"], [" that the film is legal.", "B"]], "ok": [["Using public domain songs", "A"], [" ensures", "F"], [" that the film is legal.", "B"]], "lab": {"tr": {"A": "özne: tek bir eylem", "B": ""}, "en": {"A": "subject: one action", "B": ""}}, "n": {"tr": ["Öznenin başında {using} var. Yani özne bir eylem: şarkıları kullanmak.", "{Songs} çoğul diye {ensure} yazılmış. Ama özne tek bir eylem.", "Tekil yüklem kullanıyoruz: {ensures.}", "Kısaca: {i n g} ya da {to} ile başlayan özne tekildir."], "en": ["The subject starts with using. So the subject is an action: using the songs.", "Because songs is plural, someone wrote ensure. But the subject is one action.", "Use a singular verb: ensures.", "In short: a subject that starts with an ing word or with to is singular."]}}, "f3": {"bad": [["The committee", "A"], [" released", "B"], [" their", "X"], [" report.", "C"]], "ok": [["The committee", "A"], [" released", "B"], [" its", "F"], [" report.", "C"]], "lab": {"tr": {"A": "tekil isim", "B": "yüklem", "C": ""}, "en": {"A": "singular noun", "B": "verb", "C": ""}}, "n": {"tr": ["{The committee}, yani kurul. İçinde çok kişi olsa da tek bir grup. Tekil.", "{Their} çoğul zamir. Tekil isme uymaz.", "Tekil isim için {its} kullanıyoruz.", "Kısaca: zamir, yerini tuttuğu isimle sayıca aynı olmalı. {Company, team, committee} için {it} ve {its.}"], "en": ["The committee has many people, but it is one group. It is singular.", "Their is a plural pronoun. It does not match a singular noun.", "For a singular noun, use its.", "In short: a pronoun must match its noun in number. Company, team, and committee take it and its."]}}, "f4": {"bad": [["The octopus can change", "A"], [" it's", "X"], [" color.", "C"]], "ok": [["The octopus can change", "A"], [" its", "F"], [" color.", "C"]], "lab": {"tr": {"A": "", "C": "kimin rengi? ahtapotun"}, "en": {"A": "", "C": "whose color? the octopus's"}}, "n": {"tr": ["Burada ahtapotun rengi kastediliyor. Yani sahiplik var.", "{It's}, yani {it is.} {It is color} anlamsız.", "Sahiplik için kesme işaretsiz {its.}", "Kısaca: {its} onun demek, {it's} ise {it is.} {Their} onların, {there} orada, {they're} ise {they are.}"], "en": ["The color belongs to the octopus. So this is possession.", "It's means it is. It is color makes no sense.", "For possession, use its with no apostrophe.", "In short: its shows possession, it's means it is. Their is possession, there is a place, they're means they are."]}}, "f5": {"bad": [["Place your", "A"], [" hand's", "X"], [" on the table.", "B"]], "ok": [["Place your", "A"], [" hands", "F"], [" on the table.", "B"]], "lab": {"tr": {"A": "", "B": ""}, "en": {"A": "", "B": ""}}, "n": {"tr": ["Burada eller hiçbir şeye sahip değil. Sadece çoğul.", "Kesme işareti sahiplik gösterir. Sahiplik yoksa konmaz.", "Sadece s ekliyoruz: {hands.}", "Kısaca: tekil sahiplikte kesme ve s, çoğulda sadece s, çoğul sahiplikte s ve kesme."], "en": ["The hands do not own anything here. They are just plural.", "An apostrophe shows possession. No possession means no apostrophe.", "Just add s: hands.", "In short: singular possessive is apostrophe s, plural is just s, plural possessive is s apostrophe."]}}, "f6": {"bad": [["In 2023,", "A"], [" the team", "B"], [" publishing", "X"], [" a study.", "C"]], "ok": [["In 2023,", "A"], [" the team", "B"], [" published", "F"], [" a study.", "C"]], "lab": {"tr": {"A": "", "B": "özne", "C": ""}, "en": {"A": "", "B": "subject", "C": ""}}, "n": {"tr": ["Özne {the team.} Peki takım ne yaptı?", "{Publishing} tek başına yüklem olamaz. Cümle yarım kalıyor.", "Çekimli bir yüklem lazım: {published.}", "Kısaca: her cümlenin çekimli bir yüklemi olmalı. {i n g}, {to} ve {having} tek başına yetmez."], "en": ["The subject is the team. So what did the team do?", "Publishing cannot be the main verb on its own. The sentence stays unfinished.", "We need a finite verb: published.", "In short: every sentence needs a finite verb. An ing word, to, or having is not enough on its own."]}}, "f7": {"bad": [["A decade later,", "A"], [" Land", "B"], [" uses", "X"], [" the filter.", "C"]], "ok": [["A decade later,", "A"], [" Land", "B"], [" used", "F"], [" the filter.", "C"]], "lab": {"tr": {"A": "zaman ipucu: geçmiş", "B": "özne", "C": ""}, "en": {"A": "time clue: past", "B": "subject", "C": ""}}, "n": {"tr": ["{A decade later}, geçmişte olmuş bir olayı anlatıyor. Metin geçmiş zamanda.", "{Uses} geniş zaman. Metnin zamanıyla uyuşmuyor.", "Geçmiş zaman kullanıyoruz: {used.}", "Kısaca: zaman ipucunu bul. {In 1939} geçmiş zaman, {each night} geniş zaman, {by the time} ise {had.}"], "en": ["A decade later describes an event in the past. The text is in the past tense.", "Uses is present tense. It does not match the text.", "Use the past tense: used.", "In short: find the time clue. In 1939 means past, each night means present, by the time means had."]}}, "f8": {"bad": [["Using a telescope,", "A"], [" a comet was spotted.", "X"]], "ok": [["Using a telescope,", "A"], [" the astronomer", "F"], [" spotted a comet.", "B"]], "lab": {"tr": {"A": "giriş: kim kullanıyor?", "B": ""}, "en": {"A": "opening: who is using it?", "B": ""}}, "n": {"tr": ["{Using a telescope}, yani teleskop kullanarak. Peki teleskobu kim kullanıyor?", "Virgülden hemen sonra {a comet} gelmiş. Kuyruklu yıldız teleskop kullanamaz.", "Virgülden sonra işi yapan kişi gelmeli: {the astronomer.}", "Kısaca: giriş ifadesinden sonra, virgülün hemen arkasına o işi yapan gelir."], "en": ["Using a telescope. So who is using the telescope?", "Right after the comma comes a comet. A comet cannot use a telescope.", "The one doing the action must come after the comma: the astronomer.", "In short: after an opening phrase, the doer of that action comes right after the comma."]}}};
